CREATE TRIGGER geometry_chunks_immutable_update BEFORE UPDATE ON geometry_chunks
  BEGIN SELECT RAISE(ABORT,'geometry chunks are immutable'); END;
CREATE TRIGGER geometry_chunks_immutable_delete BEFORE DELETE ON geometry_chunks
  BEGIN SELECT RAISE(ABORT,'geometry chunks are retained'); END;
CREATE TRIGGER geometry_revisions_immutable_update BEFORE UPDATE ON geometry_revisions
  BEGIN SELECT RAISE(ABORT,'geometry revisions are immutable'); END;
CREATE TRIGGER geometry_revisions_immutable_delete BEFORE DELETE ON geometry_revisions
  BEGIN SELECT RAISE(ABORT,'geometry revisions are retained'); END;
CREATE TRIGGER geometry_revision_chunks_immutable_update BEFORE UPDATE ON geometry_revision_chunks
  BEGIN SELECT RAISE(ABORT,'geometry chunk references are immutable'); END;
CREATE TRIGGER geometry_revision_chunks_immutable_delete BEFORE DELETE ON geometry_revision_chunks
  BEGIN SELECT RAISE(ABORT,'geometry chunk references are retained'); END;
CREATE TRIGGER geometry_deltas_immutable_update BEFORE UPDATE ON geometry_deltas
  BEGIN SELECT RAISE(ABORT,'geometry deltas are immutable'); END;
CREATE TRIGGER geometry_deltas_immutable_delete BEFORE DELETE ON geometry_deltas
  BEGIN SELECT RAISE(ABORT,'geometry deltas are retained'); END;
CREATE TRIGGER spatial_regions_insert AFTER INSERT ON spatial_regions BEGIN
  INSERT INTO spatial_regions_rtree VALUES(new.id,
    max(-1e30,min(1e30,new.min_x)),max(-1e30,min(1e30,new.max_x)),
    max(-1e30,min(1e30,new.min_y)),max(-1e30,min(1e30,new.max_y)),
    max(-1e30,min(1e30,new.min_z)),max(-1e30,min(1e30,new.max_z)));
END;
CREATE TRIGGER spatial_regions_update AFTER UPDATE ON spatial_regions BEGIN
  DELETE FROM spatial_regions_rtree WHERE id=old.id;
  INSERT INTO spatial_regions_rtree VALUES(new.id,
    max(-1e30,min(1e30,new.min_x)),max(-1e30,min(1e30,new.max_x)),
    max(-1e30,min(1e30,new.min_y)),max(-1e30,min(1e30,new.max_y)),
    max(-1e30,min(1e30,new.min_z)),max(-1e30,min(1e30,new.max_z)));
END;
CREATE TRIGGER spatial_regions_delete AFTER DELETE ON spatial_regions BEGIN
  DELETE FROM spatial_regions_rtree WHERE id=old.id;
END;
CREATE TRIGGER object_bounds_insert AFTER INSERT ON object_bounds BEGIN
  INSERT INTO spatial_regions(object_id,array_name,min_x,min_y,min_z,max_x,max_y,max_z)
    VALUES(new.object_id,'',new.min_x,new.min_y,new.min_z,new.max_x,new.max_y,new.max_z);
END;
CREATE TRIGGER object_bounds_update AFTER UPDATE ON object_bounds
WHEN old.min_x!=new.min_x OR old.min_y!=new.min_y OR old.min_z!=new.min_z
  OR old.max_x!=new.max_x OR old.max_y!=new.max_y OR old.max_z!=new.max_z BEGIN
  UPDATE spatial_regions SET min_x=new.min_x,min_y=new.min_y,min_z=new.min_z,
    max_x=new.max_x,max_y=new.max_y,max_z=new.max_z WHERE object_id=new.object_id AND array_name='';
END;
CREATE TRIGGER object_bounds_delete AFTER DELETE ON object_bounds BEGIN
  DELETE FROM spatial_regions WHERE object_id=old.object_id AND array_name='';
END;
CREATE TRIGGER store_identity_immutable_update BEFORE UPDATE ON store_identity BEGIN SELECT RAISE(ABORT,'store identity is immutable'); END;
CREATE TRIGGER store_identity_immutable_delete BEFORE DELETE ON store_identity BEGIN SELECT RAISE(ABORT,'store identity is retained'); END;
CREATE TRIGGER object_revisions_UPDATE BEFORE UPDATE ON object_revisions BEGIN SELECT RAISE(ABORT,'object history is immutable and retained'); END;
CREATE TRIGGER object_revisions_DELETE BEFORE DELETE ON object_revisions BEGIN SELECT RAISE(ABORT,'object history is immutable and retained'); END;
CREATE TRIGGER relationship_revisions_UPDATE BEFORE UPDATE ON relationship_revisions BEGIN SELECT RAISE(ABORT,'object history is immutable and retained'); END;
CREATE TRIGGER relationship_revisions_DELETE BEFORE DELETE ON relationship_revisions BEGIN SELECT RAISE(ABORT,'object history is immutable and retained'); END;
