CREATE TRIGGER object_relationship_deltas_DELETE BEFORE DELETE ON object_relationship_deltas BEGIN SELECT RAISE(ABORT,'object history is immutable and retained'); END;
CREATE TRIGGER objects_history_INSERT AFTER INSERT ON objects BEGIN INSERT INTO history_dirty_objects VALUES(new.uuid) ON CONFLICT(uuid) DO NOTHING; END;
CREATE TRIGGER fibers_history_INSERT AFTER INSERT ON fibers BEGIN INSERT INTO history_dirty_objects SELECT uuid FROM objects WHERE id=new.object_id ON CONFLICT(uuid) DO NOTHING; END;
CREATE TRIGGER surfaces_history_INSERT AFTER INSERT ON surfaces BEGIN INSERT INTO history_dirty_objects SELECT uuid FROM objects WHERE id=new.object_id ON CONFLICT(uuid) DO NOTHING; END;
CREATE TRIGGER tracks_history_INSERT AFTER INSERT ON tracks BEGIN INSERT INTO history_dirty_objects SELECT uuid FROM objects WHERE id=new.object_id ON CONFLICT(uuid) DO NOTHING; END;
CREATE TRIGGER object_tags_history_INSERT AFTER INSERT ON object_tags BEGIN INSERT INTO history_dirty_objects SELECT uuid FROM objects WHERE id=new.object_id ON CONFLICT(uuid) DO NOTHING; END;
CREATE TRIGGER geometry_heads_history_INSERT AFTER INSERT ON geometry_heads BEGIN INSERT INTO history_dirty_objects VALUES(new.object_uuid) ON CONFLICT(uuid) DO NOTHING; END;
CREATE TRIGGER edges_history_INSERT AFTER INSERT ON edges BEGIN INSERT INTO history_dirty_edges VALUES(new.uuid) ON CONFLICT(uuid) DO NOTHING;INSERT INTO history_dirty_objects SELECT uuid FROM objects WHERE id IN (new.a_id,new.b_id) ON CONFLICT(uuid) DO NOTHING; END;
CREATE TRIGGER edge_tags_history_INSERT AFTER INSERT ON edge_tags BEGIN INSERT INTO history_dirty_edges SELECT uuid FROM edges WHERE id=new.edge_id ON CONFLICT(uuid) DO NOTHING;INSERT INTO history_dirty_objects SELECT o.uuid FROM objects o JOIN edges e ON o.id=e.a_id OR o.id=e.b_id WHERE e.id=new.edge_id ON CONFLICT(uuid) DO NOTHING; END;
CREATE TRIGGER edge_geometry_bindings_history_INSERT AFTER INSERT ON edge_geometry_bindings BEGIN INSERT INTO history_dirty_edges SELECT uuid FROM edges WHERE id=new.edge_id ON CONFLICT(uuid) DO NOTHING;INSERT INTO history_dirty_objects SELECT o.uuid FROM objects o JOIN edges e ON o.id=e.a_id OR o.id=e.b_id WHERE e.id=new.edge_id ON CONFLICT(uuid) DO NOTHING; END;
