CREATE TRIGGER geometry_dependencies_insert AFTER INSERT ON edges BEGIN INSERT OR IGNORE INTO geometry_edge_dependencies SELECT new.id,new.a_id,'',-1 WHERE coalesce(json_array_length(new.a_dependencies,'$.points'),0)=0 OR coalesce(json_array_length(new.a_dependencies,'$.channels'),0)>0 OR EXISTS(SELECT 1 FROM json_each(new.a_dependencies,'$.points') p WHERE json_extract(p.value,'$.array') NOT IN ('point_ids','control_point_ids'));INSERT OR IGNORE INTO geometry_edge_dependencies SELECT new.id,new.a_id,json_extract(p.value,'$.array'),json_extract(p.value,'$.index[0]') FROM json_each(new.a_dependencies,'$.points') p WHERE json_extract(p.value,'$.array') IN ('point_ids','control_point_ids');INSERT OR IGNORE INTO geometry_edge_dependencies SELECT new.id,new.b_id,'',-1 WHERE coalesce(json_array_length(new.b_dependencies,'$.points'),0)=0 OR coalesce(json_array_length(new.b_dependencies,'$.channels'),0)>0 OR EXISTS(SELECT 1 FROM json_each(new.b_dependencies,'$.points') p WHERE json_extract(p.value,'$.array') NOT IN ('point_ids','control_point_ids'));INSERT OR IGNORE INTO geometry_edge_dependencies SELECT new.id,new.b_id,json_extract(p.value,'$.array'),json_extract(p.value,'$.index[0]') FROM json_each(new.b_dependencies,'$.points') p WHERE json_extract(p.value,'$.array') IN ('point_ids','control_point_ids'); END;
CREATE TRIGGER geometry_dependencies_update AFTER UPDATE OF a_id,b_id,a_dependencies,b_dependencies ON edges BEGIN DELETE FROM geometry_edge_dependencies WHERE edge_id=old.id;INSERT OR IGNORE INTO geometry_edge_dependencies SELECT new.id,new.a_id,'',-1 WHERE coalesce(json_array_length(new.a_dependencies,'$.points'),0)=0 OR coalesce(json_array_length(new.a_dependencies,'$.channels'),0)>0 OR EXISTS(SELECT 1 FROM json_each(new.a_dependencies,'$.points') p WHERE json_extract(p.value,'$.array') NOT IN ('point_ids','control_point_ids'));INSERT OR IGNORE INTO geometry_edge_dependencies SELECT new.id,new.a_id,json_extract(p.value,'$.array'),json_extract(p.value,'$.index[0]') FROM json_each(new.a_dependencies,'$.points') p WHERE json_extract(p.value,'$.array') IN ('point_ids','control_point_ids');INSERT OR IGNORE INTO geometry_edge_dependencies SELECT new.id,new.b_id,'',-1 WHERE coalesce(json_array_length(new.b_dependencies,'$.points'),0)=0 OR coalesce(json_array_length(new.b_dependencies,'$.channels'),0)>0 OR EXISTS(SELECT 1 FROM json_each(new.b_dependencies,'$.points') p WHERE json_extract(p.value,'$.array') NOT IN ('point_ids','control_point_ids'));INSERT OR IGNORE INTO geometry_edge_dependencies SELECT new.id,new.b_id,json_extract(p.value,'$.array'),json_extract(p.value,'$.index[0]') FROM json_each(new.b_dependencies,'$.points') p WHERE json_extract(p.value,'$.array') IN ('point_ids','control_point_ids'); END;
CREATE TRIGGER source_identity_object_insert AFTER INSERT ON objects
 WHEN new.kind='point_collection' BEGIN
 INSERT OR IGNORE INTO source_identity_dirty VALUES(new.uuid); END;
CREATE TRIGGER source_identity_object_update AFTER UPDATE OF meta,storage_ref,kind ON objects
 WHEN (new.kind='point_collection' OR old.kind='point_collection') AND
 (new.kind IS NOT old.kind OR
 json_extract(new.meta,'$.source.origin') IS NOT json_extract(old.meta,'$.source.origin') OR
 json_extract(new.meta,'$.source.source_collection_id') IS NOT json_extract(old.meta,'$.source.source_collection_id') OR
 (json_extract(new.meta,'$.source.origin') IS NULL AND new.storage_ref IS NOT old.storage_ref)) BEGIN
 INSERT OR IGNORE INTO source_identity_dirty VALUES(new.uuid); END;
CREATE TRIGGER source_identity_head_insert AFTER INSERT ON geometry_heads
 WHEN (SELECT kind FROM objects WHERE uuid=new.object_uuid)='point_collection' BEGIN
 INSERT OR IGNORE INTO source_identity_dirty VALUES(new.object_uuid); END;
CREATE TRIGGER source_identity_head_update AFTER UPDATE ON geometry_heads
 WHEN (SELECT kind FROM objects WHERE uuid=new.object_uuid)='point_collection' BEGIN
 INSERT OR IGNORE INTO source_identity_dirty VALUES(new.object_uuid); END;
CREATE TRIGGER source_identity_head_delete AFTER DELETE ON geometry_heads
 WHEN EXISTS(SELECT 1 FROM objects WHERE uuid=old.object_uuid AND kind='point_collection') BEGIN
 INSERT OR IGNORE INTO source_identity_dirty VALUES(old.object_uuid); END;
